custom_scss:
:root {
    div#page-login {
        background: url(/files/01.svg);
        background-repeat: no-repeat;
        background-size: cover;
        display: flex;
        align-items: center;
        justify-content: flex-end; /* Align login container to the right */
        height: 100vh;
        padding: 0 5%; /* Add some padding to the right and left */
    }

    /* Main rectangle container */
    .login-container {
        display: flex;
        width: 50%; /* Adjust width to make it smaller */
        max-width: 500px; /* Set a max width */
        height: 500px;
        background-color: white; /* Set container background to white */
        border-radius: var(--border-radius-md);
        box-shadow: 0px 4px 12px rgba(0, 0, 0, 0.1);
        overflow: hidden;
    }

    /* Remove left-side image container */
    .login-image {
        display: none;
    }

    /* Right side login form (adjusted width for single column layout) */
    .login-form {
        width: 100%; /* Take full width since no image */
        padding: 30px; /* Slightly reduce padding */
        display: flex;
        flex-direction: column;
        justify-content: center;
        text-align: center;
        background-color: rgba(255, 255, 255, 0.9);
    }

    /* Added padding to the form */
    .form-signin {
        padding: 20px; /* Add padding to the form */
    }

    /* Set white background for the for-login section */
    .for-login {
        background-color: white; /* Add white background */ 
        border-radius: var(--border-radius-md); /* Optional: add border radius */
         box-shadow: 0 4px 8px 0 rgba(0, 0, 0, 0.2), 0 6px 20px 0 rgba(0, 0, 0, 0.19);
    }

    /* Logo above login */
    .login-logo {
        margin-bottom: 20px;
    }

    .login-logo img {
        max-width: 150px;
    }

    .page-card-head h4 {
        color: #333;
        margin-bottom: 20px;
        font-size: 24px;
    }

    .page-card {
        padding: 20px; /* Remove padding if needed */
        background: none; /* Ensure no background */
        border: none; /* Remove border */
    }

    /* Style the login button */
    .btn-login {
        background-color: purple; /* Change button color to purple */
        color: white; /* Change button text color to white */
        border: none; /* Remove border */
    }

    /* Hover effect for button */
    .btn-login:hover {
        background-color: darkviolet; /* Darker purple on hover */
    }

    /* Hide unnecessary elements */
    .navbar-light {
        display: none;
    }

    /* Ensure card is centered */
    .page-card-head {
        display: block;
    }

    /* Remove border and padding from login-content page-card */
    .login-content.page-card {
        padding: 0; /* Remove padding */
        border: none; /* Remove border */
        background: none; /* Ensure no background */
    }
    .app-logo {
        content: url(/files/INVOIX%20FAVICO.png); /* Replace the logo dynamically */
        max-width: 150px; /* Restrict the logo width */
        height: auto; /* Maintain aspect ratio */
    }


    .for-login .page-card .page-card-body .email-field input, .for-login .page-card .page-card-body .password-field input, .for-forgot .page-card .page-card-body .email-field input, .for-forgot .page-card .page-card-body .password-field input, .for-login-with-email-link .page-card .page-card-body .email-field input, .for-login-with-email-link .page-card .page-card-body .password-field input, .for-signup .page-card .page-card-body .email-field input, .for-signup .page-card .page-card-body .password-field input, .for-email-login .page-card .page-card-body .email-field input, .for-email-login .page-card .page-card-body .password-field input {
    padding-left: 35px;
    padding-right: 35px;
    }
    .page-title .title-area .title-text {
        color: blue !important;
    }

}



/* Updated styles for page cards in different sections */
.for-login .page-card, 
.for-forgot .page-card, 
.for-login-with-email-link .page-card, 
.for-signup .page-card, 
.for-email-login .page-card {
    padding: 0; /* Remove padding */
    background-color: #fff; /* Keep white background */
    max-width: 400px; /* Keep max width */
    margin: 0 auto; /* Center the card */
    border-radius: var(--border-radius-md); /* Keep border radius */
    border: none; /* Remove border */
}

